import path from 'node:path'
import { Router } from 'express'
import type { Response } from 'express'
import { VIDEO_ID_PATTERN, isPlaylistAllowed } from '../config'
import type { AppConfig } from '../config'
import { liveRelayDirFor, touchLiveRelay } from '../live-relay'
import { logger } from '../logger'
import { ensureVodSegment } from '../vod-relay'
import { resolveVideoIdForPosition } from '../refresh'

const POSITION_PATTERN = /^(\d+)$/
/**
 * Allows only file names generated by ffmpeg (`live-relay.ts`: `live.m3u8` and segments such as `live0.ts`)
 * and VOD muxed segments (`seg0.ts` etc., `vod-relay.ts`). Not accepting arbitrary file names is the path traversal defense.
 */
const LIVE_FILE_PATTERN = /^live\.m3u8$|^live\d+\.ts$|^seg\d+\.ts$/
const VOD_SEGMENT_PATTERN = /^seg(\d+)\.ts$/

/**
 * Shared handler serving the Live republished files (master playlist / segments) for a videoId.
 * Called from both `GET /{playlistId}/{position}/live/{file}` and `GET /live/{videoId}/{file}`,
 * each passing a videoId it has already resolved in its own way.
 * Viewing clients keep re-fetching the master playlist / segments, so `touchLiveRelay()` updates
 * the videoId's `lastAccessedAt`.
 * This keeps `evictIdleLiveRelays()` from mistaking a process in use for idle.
 */
function serveLiveFile(
  config: AppConfig,
  videoId: string,
  file: string,
  res: Response
): void {
  if (!LIVE_FILE_PATTERN.test(file)) {
    res.status(404).json({ error: 'invalid file' })
    return
  }
  touchLiveRelay(videoId)
  const baseDir = liveRelayDirFor(config, videoId)
  const filePath = path.join(baseDir, file)
  // file is already validated by LIVE_FILE_PATTERN, but also check explicitly right before sending
  // that the resolved path is under baseDir. This lets static analysis tools track the safety.
  if (!path.resolve(filePath).startsWith(path.resolve(baseDir) + path.sep)) {
    res.status(404).json({ error: 'invalid file' })
    return
  }
  const segment = VOD_SEGMENT_PATTERN.exec(file)
  if (segment === null) {
    res.sendFile(filePath)
    return
  }
  ensureVodSegment(videoId, Number(segment[1]))
    .then((segmentPath) => {
      if (segmentPath === null) {
        res.status(404).json({ error: 'unknown segment' })
        return
      }
      res.sendFile(segmentPath)
    })
    .catch((err: unknown) => {
      logger.error(
        'relay.live.segment.failed',
        'Failed to prepare live segment',
        {
          video_id: videoId,
          segment: file,
          error: err instanceof Error ? err : new Error(String(err)),
        }
      )
      res.status(502).json({ error: 'failed to prepare segment' })
    })
}

/**
 * Router grouping the two routes (via Playlist/position, or by videoId directly) that serve the local HLS files
 * republished by `ensureLiveRelay()` in Live `proxy` mode.
 */
export function liveRouter(config: AppConfig): Router {
  const router = Router()

  router.get('/:playlistId/:position/live/:file', (req, res) => {
    const { playlistId, position: positionParam, file } = req.params
    if (!isPlaylistAllowed(config, playlistId)) {
      res.status(404).json({ error: 'unknown playlistId' })
      return
    }

    const positionMatch = POSITION_PATTERN.exec(positionParam)
    if (!positionMatch) {
      res.status(404).json({ error: 'invalid position' })
      return
    }
    // resolveVideoIdForPosition() is an expensive async call that may trigger a yt-dlp Refresh,
    // so validate the file format before it to avoid a pointless Refresh for an invalid file.
    if (!LIVE_FILE_PATTERN.test(file)) {
      res.status(404).json({ error: 'invalid file' })
      return
    }
    const position = Number(positionMatch[1])

    resolveVideoIdForPosition(config, playlistId, position)
      .then((resolved) => {
        if ('error' in resolved) {
          const status = resolved.reason === 'refresh_failed' ? 502 : 404
          res.status(status).json({ error: resolved.error })
          return
        }
        serveLiveFile(config, resolved.videoId, file, res)
      })
      .catch((err: unknown) => {
        res.status(502).json({
          error: `failed to resolve position: ${(err as Error).message}`,
        })
      })
  })

  /**
   * GET /live/{videoId}/{file}
   *
   * Fetches Live republished files by videoId directly (redirected to from `../routes/video`
   * with `LIVE_DELIVERY_MODE=proxy`). It does not go through a Playlist, so it skips
   * `isPlaylistAllowed` and only validates the format with `VIDEO_ID_PATTERN`.
   */
  router.get('/live/:videoId/:file', (req, res) => {
    const { videoId, file } = req.params
    if (!VIDEO_ID_PATTERN.test(videoId)) {
      res.status(404).json({ error: 'invalid videoId' })
      return
    }
    serveLiveFile(config, videoId, file, res)
  })

  return router
}
